def stamp(I,tpl,mks,order=None):
    Hh,Ww=len(I),len(I[0])
    out=[row[:] for row in I]
    dh=(len(tpl)-1)//2; dw=(len(tpl[0])-1)//2
    o_ks=mks if order=='asc' else sorted(mks,reverse=True)
    for s in o_ks:
        mr,mc=s
        for i in range(len(tpl)):
            for j in range(len(tpl[0])):
                rr,cc=mr+dh-i,mc-dw+j
                if 0<=rr<Hh and 0<=cc<Ww:
                    out[rr][cc]=tpl[i][j]
    return out

